WTOOLS['tool-neshima'].ex.push(
  ["איזה נחיר נושם עכשיו", "שלוש פעמים ביום, בבוקר, בצהריים ובערב, עצרו לרגע ושימו לב דרך איזה נחיר האוויר עובר בקלות רבה יותר, הימני, השמאלי, או שניהם באותה מידה. אפשר לסגור בעדינות נחיר אחד ואחר כך את השני, ולהרגיש. הצד הימני קשור לנתינה ולמה שיוצא מאיתנו אל העולם, השמאלי לקבלה ולמה שנכנס, ושניהם יחד לאיזון ביניהם. רשמו בכל פעם מה מצאתם ומה עשיתם באותה שעה. לא משנים כלום, רק מכירים את הקצב שלכם."],
  ["לאן הנשימה שלי מגיעה", "שכבו או שבו בנוחות, יד אחת על הבטן ויד אחת על החזה. נשמו כרגיל, בלי לשנות, ושימו לב איזו יד זזה יותר. אחר כך שאלו אם האוויר מרגיש כאילו הוא עולה גם לראש. נשימה שמגיעה לבטן מזינה את החיות של הגוף, נשימה שנשארת בחזה נושאת את המטען הרגשי, ונשימה שמרגישה עד הראש קשורה להבנה ולבהירות. כתבו איפה היא נוטה להיעצר אצלכם, ואל איזו קומה קשה לה להגיע."],
  ["חוטם, סרעפת וטבור", "שלוש נשימות שבונות זו על זו. נשימה מהחוטם: שאפו לאט דרך האף, והרגישו את האוויר עולה אל הראש, ונשפו לאט. נשימה מהסרעפת: שאפו אל החזה ואל מתחת לצלעות, הרגישו את הצלעות מתרחבות לצדדים, ונשפו כשהן נאספות פנימה. נשימה מהטבור: שאפו עמוק עד שהבטן מתמלאת כמו בלון, ובנשיפה הרגישו את האוויר עולה מהבטן דרך הריאות ויוצא. שלוש נשימות מכל סוג, ובסוף כמה נשימות חופשיות."],
  ["ארבע נשימות, ארבעה כוחות", "סקירה קצרה של מה שקורה בפנים, ארבע נשימות איטיות לארבעה מקומות. נשימה אל הראש, ושאלה: מה אני רוצה עכשיו? נשימה אל החזה: על מה אני חושב או חושבת? נשימה אל הלב והריאות: מה אני מרגיש או מרגישה? נשימה אל הבטן: מה אני עושה, או עומד או עומדת לעשות? אחרי הסבב בחרו איפה הכי סוער, ואליו כוונו עוד שלוש נשימות. אם יש שם עומס, נשימות איטיות. אם יש שם כבדות, נשימות מעט מהירות יותר."],
  ["הקצב המלא, בלי אותיות", "למי שכבר נוח עם ההשהיה. שאפו דרך האף, השהו את האוויר כעשר שניות ותנו לו להגיע אל הראש. נשפו לאט דרך האף, כחמש שניות, אל החזה. שאפו שוב דרך האף, השהו כשש שניות, והרגישו את האוויר ממלא את הלב והריאות. ונשפו לאט דרך הפה, כחמש שניות, אל הבטן. זה סבב אחד. שלושה עד חמישה סבבים, ובין סבב לסבב כמה נשימות חופשיות. המספרים הם כיוון ולא מבחן. אם לא הספקתם, פשוט נושמים שוב."],
  ["רוחב לב", "שאפו לאט אל מרכז החזה, כשש שניות, ותנו לצלעות להתרחב לצדדים כאילו המקום הזה נעשה גדול יותר. בנשיפה האיטית אמרו בלב: יש כאן מקום גם למה שלא מושלם. חמש נשימות כאלה ביום, ובמיוחד ברגע שאתם שמים לב שאתם מקפידים, על עצמכם או על אחרים. ההקפדה באה ממקום טוב, מהרצון שהכול יהיה שלם, אבל החיים הם מקום שיש בו טעויות ותיקונים. רוחב לב הוא היכולת להכיל את זה בלי להתכווץ."],
  ["אחרי אכזבה", "כשמשהו לא יצא כמו שקיוויתם, שבו כמה דקות ונשמו נשימות איטיות, ארוכות ורכות. בכל נשיפה דמיינו שהיא מנקה בעדינות את המשקע שהאכזבה השאירה, כמו מים שעוברים על אבן. לא מנסים לפתור ולא להבין עכשיו. אחר כך כתבו שורה אחת: מה אולי מתחיל להיבנות דווקא מתוך התקופה הזאת. יש נחלים שנראים יבשים לגמרי, ובכל זאת המים זורמים מתחת."],
  ["המקום שהפסקתי לנשום אליו", "בחרו מקום בגוף שקשה לכם להביא אליו אוויר, או שאתם כמעט לא מרגישים. שבו בשקט ושאלו, בלי ללחוץ על תשובה: ממתי המקום הזה סגור? האם קרה משהו, אפילו קטן, שאחריו הפסקתי לשים אליו לב? אחר כך שאפו לאט, וכוונו אליו את האוויר בעדינות, כמו דפיקה רכה על דלת. שלוש נשימות, שלוש פעמים ביום. לא פורצים, רק חוזרים לבקר."],
  ["הכאב כאיתות", "כשכאב מופיע, לפני שמתכווצים מולו, אמרו לעצמכם: יש כאן חיים שמבקשים אוויר. מקום שכואב הוא מקום רגיש וחי, שמסמן שחסר לו משהו. שאפו לאט אל השוליים של הכאב, לא אל המרכז שלו, ותנו לאוויר להתפשט סביבו. בנשיפה תנו לשרירים שמסביב להרפות. כמה נשימות, בלי לדרוש מהכאב להיעלם. התרגיל הזה מלווה את הטיפול ואת הבירור הרפואי, ולא מחליף אותם."],
  ["לחבר בין שני מקומות", "כשיש מתח, לרוב יש שני מקומות שמושכים זה מול זה, הלסת והבטן, הכתף והירך, הצוואר והגב התחתון. מצאו את שני המקומות אצלכם. שאפו אל הראשון ונשפו מתוך השני, ואחר כך הפוך. אחרי כמה סבבים, נשמו נשימה אחת ארוכה שממלאת את שניהם יחד, כאילו ביניהם עובר ערוץ פתוח. שימו לב מה משתנה בכל אחד מהם."],
  ["נשימה לידיים ולרגליים", "סקירה של הגפיים, בשלוש תחנות לכל יד ולכל רגל. ביד: מהכתף עד המרפק, מהמרפק עד פרק כף היד, ומכף היד עד קצות האצבעות. ברגל: מהמותן עד הברך, מהברך עד הקרסול, ומהקרסול עד קצות האצבעות. בכל תחנה שתיים או שלוש נשימות איטיות, ובכל שאיפה הובילו במחשבה את האוויר לאורך הקטע, עד שהוא מרגיש חם ומלא. מתחילים ביד אחת ביום ומוסיפים בהדרגה, לא את כל הגוף בפעם הראשונה."],
  ["זמזום בנשיפה", "שאפו לאט דרך האף. בנשיפה סגרו את השפתיים והוציאו את האוויר בזמזום רך וארוך, ממממ, כמו מנגינה שקטה. הרגישו איפה הרטט יושב: בשפתיים, באף, בפנים, בגרון או בחזה. חמש עד עשר נשימות כאלה. הקול הוא נשימה שקיבלה צורה, והזמזום מוביל אותה למקומות שנשימה רגילה לא תמיד מגיעה אליהם. אם יש מנגינה שאתם אוהבים, אפשר לזמזם אותה."],
  ["חמשת מקומות הדיבור", "הקול יוצא מחמישה מקומות בפה, ואפשר לעבור עליהם לאט, על הנשיפה. הגרון: א, ה, ח, ע. החך: ג, י, כ, ק. הלשון: ד, ט, ל, נ, ת. השיניים: ז, ס, ש, ר, צ. השפתיים: ב, ו, מ, פ. בכל נשיפה אמרו בשקט קבוצה אחת, לאט, והרגישו את המקום שבו הצליל נוצר. שימו לב באיזה מקום הצליל יוצא בקלות, ובאיזה מקום משהו נתפס או מתכווץ, ושם אפשר להוסיף עוד נשימה."],
  ["המילים על הנשיפה", "המילים שלנו נישאות על האוויר שיוצא. לפני שיחה חשובה, או כשאתם מרגישים שאתם מדברים מהר מדי, נשמו נשימה אחת מלאה, ואמרו את המשפט הבא על הנשיפה האיטית, משפט קצר אחד. שימו לב השבוע לרגעים שבהם אתם מדברים בלי אוויר, ממשיכים ומשפטים מצטופפים. ברגע כזה עצרו, נשמו, והמשיכו."],
  ["ארבע עצירות ביום", "קבעו ארבע עצירות קבועות ביממה, בערך כל שש שעות: בבוקר, בצהריים, בערב ולפני השינה. בכל עצירה, דקה אחת של נשימה איטית, גם ביום רגוע וגם כשהכול בסדר. מה שמתורגל ברגיעה זמין ברגע של לחץ. מי שהקצב הקבוע לא מתאים לו, יכול לבחור ארבע עצירות לפי הצורך, ובלבד שיהיו ארבע."],
  ["נשימה בהליכה", "בהליכה בקצב נוח, התאימו את הנשימה לצעדים: שאיפה לאורך שלושה או ארבעה צעדים, ונשיפה לאורך ארבעה או חמישה. בכל שאיפה הובילו את האוויר במחשבה למטה, דרך הבטן והירכיים עד כפות הרגליים, והרגישו את הרגליים מתמלאות כוח. עשר עד עשרים דקות. אם הקצב לא נוח, שנו את מספר הצעדים עד שהנשימה זורמת בלי מאמץ."],
  ["מהרחב או מהנקודה", "יש אנשים שקל להם להתחיל מתחושה רחבה של כל הגוף, ורק אחר כך להתמקד, ויש שקל להם להתחיל מנקודה אחת ולהתרחב ממנה. שני הסגנונות טבעיים, ואין כאן ליקוי. השבוע נסו את שניהם. ביום אחד התחילו בנשימה שממלאת את כל הגוף, ורק אחר כך כוונו לאזור אחד. ביום הבא התחילו מנקודה אחת, למשל קצה האף, והתרחבו ממנה בהדרגה. רשמו מה היה טבעי לכם, ומשם בנו את התרגול."],
  ["לנשום כמו ילד", "תינוקות וילדים קטנים נושמים בלי מאמץ, והבטן שלהם עולה ויורדת. שכבו על הגב והניחו על הבטן חפץ קל, ספר קטן או כרית. נשמו בלי לעזור לנשימה ובלי לעצור אותה, ותנו לחפץ לעלות בשאיפה ולרדת בנשיפה מעצמו. חמש דקות. אם יש לכם הזדמנות, הסתכלו כמה רגעים על ילד או על בעל חיים ישן ושימו לב לקצב שלהם."]
);
