/* תרגילים כלליים */
const WGENERAL={"guf": [["נשימה בוקר וערב", "חמש נשימות עמוקות בבוקר ובערב. שאיפה דרך האף, נשיפה איטית."], ["שיחה עם האיבר", "אחרי כמה נשימות, הניחו יד על המקום שכואב ושאלו אותו בשקט: מה אתה צריך? מה אתה מנסה לומר לי? לא לחשוב על התשובה, אלא לחכות ולראות מה עולה."], ["יום של קלילות", "בחרו השבוע יום אחד, או חלק מיום, שבו מותר לא לקחת דברים ברצינות. בבוקר שאלו את עצמכם: האם הדבר הזה באמת חייב להיות רציני היום? שימו מוזיקה שאתם אוהבים ורקדו כמה דקות, כשאף אחד לא רואה, בלי לחשוב איך זה נראה. שירו בקול במקלחת או באוטו. עשו משהו קטן ושטותי, רק בשביל ההנאה. ואם עולה קול פנימי שאומר שזה מיותר או מגוחך, חייכו אליו והמשיכו. בערב כתבו: מה הרגשתי בגוף, ומה השתנה בדרך שבה הסתכלתי על היום.", "מי שקשה עם עצמו חי כמעט כל הזמן ברצינות, בדרישה ובשליטה. כשמפעילים את הגוף בשמחה, בתנועה, בשיר ובצחוק, הנפש מקבלת רשות להשתחרר מהמתח, ומגלה שאפשר להיות בסדר גם בלי לעשות הכול נכון."], ["ללכת עם חיוך", "השבוע, כמה פעמים ביום, חייכו בלי סיבה. אפשר להתחיל מול המראה, או בהליכה ברחוב. אם החיוך לא בא מעצמו, הרימו בעדינות את הלחיים ואת זוויות הפה, והחזיקו את החיוך חצי דקה, עם נשימה איטית. שימו לב מה קורה בעיניים, בכתפיים ובנשימה. אפשר לקבוע לזה תזכורת, למשל בכל פעם שעוברים בדלת. בערב רשמו: מתי היה קשה לחייך, ומתי זה פתח משהו.", "הגוף והרגש משפיעים זה על זה בשני הכיוונים: לא רק שמחה מביאה חיוך, אלא גם חיוך מעורר שמחה. גם חיוך מכוון, בלי סיבה, משנה את מתח השרירים בפנים ואת הנשימה, ומאותת למערכת העצבים שאפשר להירגע."], ["חיוך שמעורר מלמטה", "כמה פעמים ביום, ובמיוחד ברגע של כבדות, עצרו וחייכו, גם בלי סיבה, וגם אם צריך להרים את הלחיים בכוח. אמרו בלב: אני מעורר או מעוררת שמחה מלמטה. החזיקו את החיוך חצי דקה, ונשמו לאט. אפשר לחבר את זה לרגע קבוע, כמו הבוקר אחרי מודה אני, או לפני ארוחה. בערב רשמו: מה התעורר בי אחרי שהחיוך התחיל בגוף?", "במסורת היהודית יש עיקרון של התעוררות מלמטה: כשאדם מעורר משהו בגוף, במעשה, זה פועל למעלה, על הנפש, על הרוח ועל הנשמה. ורבי נחמן מברסלב לימד שמצווה גדולה להיות בשמחה תמיד, ושמי שאין לו שמחה יעשה את עצמו כאילו הוא שמח, כי השמחה תבוא."], ["ניעור הידיים", "בחרו חוויה או מקרה שעורר בכם רגש לא נעים. שבו רגע, ונזכרו בו עד שהרגש והתחושה בגוף מורגשים בבירור. עכשיו קומו, והתחילו לקפוץ קפיצות קלות בעזרת הברכיים, בלי להרים את כפות הרגליים מהרצפה, אם הגוף מאפשר. נערו את הידיים מהר ככל שאפשר, מהכתפיים ועד קצות האצבעות, דקה עד שלוש דקות. אחר כך עצרו, עמדו בשקט, נשמו לאט ושימו לב: מה נשאר מהרגש, ואיפה הוא מורגש עכשיו. מי שיש לו בעיה בברכיים או בשיווי המשקל, יכול לעשות את זה בישיבה, רק עם הידיים.", "הידיים הן הביטוי של הרגש: דרכן אנחנו נותנים, מקבלים, מחבקים ודוחים, ובהן הרגש נאגר כשאין לו מוצא. ניעור מהיר של הידיים, יחד עם קפיצות קלות, משחרר את המתח שנשאר בגוף אחרי חוויה קשה, וכך גם הרגש מתפנה."]], "regesh": [["שלוש שאלות על רגע אחד", "בחרו רגע מהיום שבו כעסתם, פחדתם או נסגרתם. כתבו: מה הרגשתי בגוף, מה חשבתי, ומה עשיתי."], ["מכתב לעצמי", "כתבו לעצמכם מכתב, כמו שהייתם כותבים לחבר טוב שעובר תקופה קשה."], ["דו שיח בין השכל ללב", "בחרו נושא שמטריד אתכם. כתבו מה השכל אומר עליו ומה הלב אומר, בתורות, כמו שיחה. בלי לתכנן, לתת לזה לזרום."]], "machshava": [["להחליף משפט ישן", "זהו משפט שלילי אחד שחוזר אצלכם. כתבו לידו משפט חדש שאתם רוצים להאמין בו, ואמרו אותו לעצמכם כל בוקר במשך השבוע."], ["מה זה בא ללמד אותי", "כתבו בלי צנזורה מה הקושי או המחלה אולי באים ללמד אתכם. אין תשובה נכונה, רק מה שעולה."]], "ratzon": [["עוד שלושה חודשים", "עצמו עיניים ודמיינו את עצמכם בעוד שלושה חודשים. איך הגוף מרגיש, איך נראה היום שלכם, מה השתנה. בפרטים ובצבעים."], ["הכישרונות שלי", "כתבו מה הכישרונות שאיתם הגעתם לעולם, ואחר כך שאלו: איך אני יכול או יכולה להשתמש בהם כדי להאיר גם לאחרים?"], ["לעשות בכוונה", "בחרו פעולה יומיומית אחת, ועשו אותה כל יום במודעות מלאה. למשל ארוחה: בלי טלפון ובלי מסך, שימו לב לצבעים, לריח, לטעמים ולמרקמים, ולעסו לאט. לפני הביס הראשון אמרו לעצמכם למה אתם אוכלים: אני מזין או מזינה את הגוף כדי להיות בריא, ולתת מעצמי לעולם. אפשר לבחור פעולה אחרת, כמו להכין ארוחת ערב לילדים, ולעשות אותה מתוך כוונה ואהבה, עם מחשבה טובה על מי שיאכל ממנה. בערב רשמו: מה הרגשתי כשעשיתי את זה בכוונה, ומה היה שונה.", "כשהרבה ממה שאנחנו עושים קורה על טייס אוטומטי, החיים עוברים בלי שנרגיש אותם. מודעות וכוונה מחזירות אותנו לרגע, ומחברות בין מה שאנחנו עושים לבין הרצון, למה אנחנו עושים את זה."], ["אכילה בכוונה", "השבוע, בארוחה אחת ביום, אכלו בכוונה. לפני האכילה עצרו, הסתכלו על האוכל, ואמרו ברכה, או משפט תודה במילים שלכם. אכלו לאט, בלי מסכים, והרגישו את הטעם ואת המרקם. כוונו בלב: אני אוכל או אוכלת כדי שיהיה לי כוח לעשות טוב, לעבוד, לאהוב ולתת. ואם אתם מכינים אוכל לאחרים, הכינו אותו מתוך אהבה, עם מחשבה טובה על כל מי שיאכל. בסוף הארוחה עצרו לרגע של תודה.", "במסורת החסידית לימדו שגם האכילה יכולה להיות עבודה פנימית: כשאוכלים בכוונה ובברכה, המאכל הופך מעוד צורך של הגוף לרגע של חיבור, וכך ניזונים גם הגוף וגם הנשמה."]]};

