/* קומות */
const FLOOR_ORDER = [['guf','מעשה וגוף'],['regesh','רגש ודיבור'],['machshava','מחשבה'],['ratzon','רצון']];
const floorLabel = id => (FLOOR_ORDER.find(f=>f[0]===id)||[])[1]||'';

/* מאגר התרגילים לפי מזהה */
const EX_EL_NAMES = {fire:'אש', water:'מים', air:'אוויר', earth:'אדמה'};
const EXR = {};
function regEx(id, title, text, src, srcLabel, floor){ EXR[id] = {id, title, text, src, srcLabel, floor}; }
Object.entries(WEEK_EL).forEach(([k,w]) => Object.entries(w.ex).forEach(([fl,arr]) => arr.forEach((e,i) =>
  { regEx(`el:${k}:${fl}:${i}`, e[0], e[1], 'el:'+k, 'יסוד ה'+EX_EL_NAMES[k], fl); if(e[2]) EXR[`el:${k}:${fl}:${i}`].why = e[2]; })));
Object.entries(WEEK_SF).forEach(([k,w]) => Object.entries(w.ex).forEach(([fl,arr]) => arr.forEach((e,i) =>
  regEx(`sf:${k}:${fl}:${i}`, e[0], e[1], 'sf:'+k, 'ספירת '+k, fl))));
Object.entries(WTOOLS).forEach(([k,t]) => t.ex.forEach((e,i) => { regEx(`${k}:${i}`, e[0], e[1], k, t.name, null); if(e[2]) EXR[`${k}:${i}`].why = e[2]; }));
Object.entries(WGENERAL).forEach(([fl,arr]) => arr.forEach((e,i) => { regEx(`gen:${fl}:${i}`, e[0], e[1], 'gen', 'תרגילים כלליים', fl); if(e[2]) EXR[`gen:${fl}:${i}`].why = e[2]; }));

