function pathMatch(text){
  const t = String(text||"");
  return Object.keys(PATH_MATCH).filter(k=>new RegExp(PATH_MATCH[k]).test(t));
}

/* ===== ספירות לפי אזור בגוף, לפי מפת הגוף ===== */
const SEF_THEME = {'חסד':'אהבה ונתינה, להרגיש אוהב ואהוב','גבורה':'גבולות, צמצום ויראה, והתחושה שאני ראוי','תפארת':'הרמוניה, רחמים וחמלה, על הזולת ועל עצמי','נצח':'נחישות, התמדה והוצאה אל הפועל','הוד':'הודיה, הודאה והכנעה','יסוד':'תשוקה, חשק, חיבור ותקשורת','מלכות':'הגשמה ונוכחות'};
const HB = w => new RegExp('(?:^|[^א-ת])(?:ה|ב|ו|ש|מ|ל)?(?:'+w+')(?:[^א-ת]|$)');
const SEF_BODY = [
  [HB('לימפה|בלוטות לימפה'), 'חסד'],
  [/לחץ דם|לחץ הדם|כולסטרול|מחזור הדם/, 'גבורה'],
  [HB('לב|הלב|ריאות|ריאה|חזה|קיבה|מעיים|מעי|כבד|ושט|צרבת|עיכול|קוצר נשימה|נשימה')||null, 'תפארת'],
  [/כיס המרה|לבלב|גב עליון|גב אמצעי|עמוד השדרה|מקלעת השמש|דופק/, 'תפארת'],
  [/כליה|כלייה|כליות|אדרנל|הורמונ/, ['נצח','הוד']],
  [/טחול|מערכת החיסון|חיסונית|זיהומים/, 'הוד'],
  [/אגן|רחם|מחזור|וסת|מיני|אינטימ|שלפוחית|דרכי השתן|ערמונית|שחלות|פוריות|גב תחתון|עצירות/, 'יסוד'],
  [HB('פה|לשון|שיניים|חניכיים|עור|עקב|עקבים|עצמות'), 'מלכות'],
  [/כף רגל|כפות רגליים|כפות הרגליים|עצם הזנב/, 'מלכות'],
  [HB('יד|ידיים|זרוע|זרועות|כתף|כתפיים|מרפק|מרפקים|שורש כף היד|אצבעות'), {right:'חסד',left:'גבורה'}],
  [HB('רגל|רגליים|ירך|ירכיים|ברך|ברכיים|קרסול|קרסוליים|שוק'), {right:'נצח',left:'הוד'}]
];
/* מחזיר את הספירות שמתאימות לאזורים שהוזכרו בטקסט. side: right / left / both, לצד שסומן בשאלון */
function sefFromText(text, side){
  const found = {};
  String(text||'').split(/[,.\n;]|\sו(?=[א-ת])/).forEach(cl=>{
    const sd = /ימין|ימנית|ימני/.test(cl) ? 'right' : /שמאל|שמאלית|שמאלי/.test(cl) ? 'left' : side;
    SEF_BODY.forEach(([re,sf])=>{
      const m = cl.match(re); if(!m) return;
      const list = typeof sf==='string' ? [sf] : Array.isArray(sf) ? sf : (sd==='right' ? [sf.right] : sd==='left' ? [sf.left] : [sf.right, sf.left]);
      list.forEach(x=>{ (found[x]=found[x]||new Set()).add(m[0].trim()); });
    });
  });
  const tidy = ws => { const a=[...ws]; return a.filter(w=>!a.some(o=>o!==w && w.endsWith(o))); };
  return Object.entries(found).map(([sf,ws])=>({sf, words:tidy(ws)}));
}

