    "שיעול כרוני":['tool-hatara:0' /* המשפטים שנאמרו עליי */],
    "קשיים באינטימיות ובתפקוד המיני":['tool-hatara:1' /* ההבטחות שהבטחתי לעצמי */],
    "תכיפות או קושי במתן שתן":['tool-hatara:1' /* ההבטחות שהבטחתי לעצמי */],
